const particles = []
const step = 4
const pointSize = 5

function setup() {
	createCanvas(512, 512)

	for (let x = 0; x < width; x += step) {
		for (let y = 0; y < height; y += step) {
			const p = new Particle(x + random(-4, 4), y + random(-4, 4), pointSize)
			particles.push(p)
		}
	}
}

function draw() {
	background(255)

	particles.forEach((particle) => {
		particle.update()
		particle.show(pointSize)
	})
}


// === Tab: Particle ===
class Particle {
	constructor(x, y, size) {
		this.pos = createVector(x, y)
		this.size = size
	}

	update() {
		var p = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
		const d = this.pos.dist(p)
		const w = p5.Vector.sub(this.pos, p).normalize()
		const f = 5 * smoothstep(120, 0, d)
		this.pos.add(w.mult(f))
	}

	show(pointSize) {
		stroke(0)
		strokeWeight(this.size)
		point(this.pos.x, this.pos.y)
	}
}


// === Tab: Math ===
const smoothstep = (edge0, edge1, x) => {
	x = constrain((x - edge0) / (edge1 - edge0), 0, 1)
	return x * x * (3 - 2 * x)
}

